def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    out = g.copy()
    eights = [tuple(p) for p in np.argwhere(g == 8)]
    twos = [tuple(p) for p in np.argwhere(g == 2)]

    def edge(cells):
        ys = {c[0] for c in cells}; xs = {c[1] for c in cells}
        if len(xs) == 1 and (list(xs)[0] in (0, W - 1)) and not (len(ys) == 1 and list(ys)[0] in (0, H - 1) and len(cells) > 1):
            return ('col', list(xs)[0])
        if len(ys) == 1 and list(ys)[0] in (0, H - 1):
            return ('row', list(ys)[0])
        return ('col', list(xs)[0])

    e8 = edge(eights)
    e2 = edge(twos)
    # travel direction: away from the 8 edge
    if e8[0] == 'row':
        d = (1, 0) if e8[1] == 0 else (-1, 0)
        along = 0
    else:
        d = (0, 1) if e8[1] == 0 else (0, -1)
        along = 1
    # shift direction: away from the 2 edge
    if e2[0] == 'row':
        s = (1, 0) if e2[1] == 0 else (-1, 0)
    else:
        s = (0, 1) if e2[1] == 0 else (0, -1)
    sign = d[along]
    marks = [m[along] for m in twos]
    limit = H if along == 0 else W

    for seed in eights:
        k = 0
        while True:
            a = seed[along] + k * sign
            if a < 0 or a >= limit:
                break
            cnt = sum(1 for m in marks if 0 < (m - seed[along]) * sign <= k)
            y = seed[0] + k * d[0] + cnt * s[0]
            x = seed[1] + k * d[1] + cnt * s[1]
            if 0 <= y < H and 0 <= x < W and out[y, x] == 0:
                out[y, x] = 8
            k += 1
        emit(out, f"Grow the line from seed {seed}, stepping one cell sideways at each 2-marker coordinate.")
    emit(out, "All seed lines drawn; final grid.")
    return out
